from datetime import datetime

def norm(s):
    return (s or '').lower()

cands=[]
for n in all_notes:
    title=norm(n.get('title'))
    tags=[norm(t) for t in n.get('tags',[])]
    if 'dinner' in title or any('dinner' in t for t in tags) or 'work dinner' in title:
        cands.append(n)

print('notes whose title/tags mention dinner:', len(cands))
for n in sorted(cands, key=lambda x: x['updated_at'])[-20:]:
    print(n['note_id'], n['title'], n['created_at'], 'updated', n['updated_at'], 'tags', n.get('tags'))

# Also list top N most recently updated among all_notes to inspect
